?item wdt:[property:instance of] wd:[entity:human] ;
wdt:[property:place of birth] ?placeBirth ;
wdt:[property:place of death] ?placeDeath .
?placeBirth wdt:[property:coordinate location] ?coordsBirth .
?placeDeath wdt:[property:coordinate location] ?coordsDeath .
BIND (geof:distance(?coordsBirth, ?coordsDeath) AS ?distance)
FILTER (?distance > 19000)
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
