query:
SELECT
?parent ?parentLabel ?parent_born ?parent_genderLabel ?parent_positionLabel ?child ?childLabel ?child_born ?child_genderLabel ?child_positionLabel
WHERE
{?parent wdt:P31 wd:Q5;
wdt:P106 wd:Q11774891; # occupation = ice hockey player
wdt:P27 wd:Q33; # country of citizenship = Finland
wdt:P569 ?parent_born;
wdt:P40 ?child . # has child
OPTIONAL {?parent wdt:P21 ?parent_gender.}
OPTIONAL {?parent wdt:P413 ?parent_position .}
?child wdt:P31 wd:Q5 ;
wdt:P106 wd:Q11774891; # child's occupation = ice hockey player
wdt:P569 ?child_born;
OPTIONAL {?child wdt:P21 ?child_gender.}
OPTIONAL {?child wdt:P413 ?child_position.}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
?parent ?parentLabel ?parent_born ?parent_genderLabel ?parent_positionLabel ?child ?childLabel ?child_born ?child_genderLabel ?child_positionLabel
WHERE
{?parent wdt:[property:instance of] wd:[entity:human];
wdt:[property:occupation] wd:[entity:ice hockey player]; # occupation = ice hockey player
wdt:[property:country of citizenship] wd:[entity:Finland]; # country of citizenship = Finland
wdt:[property:date of birth] ?parent_born;
wdt:[property:child] ?child . # has child
OPTIONAL {?parent wdt:[property:sex or gender] ?parent_gender.}
OPTIONAL {?parent wdt:[property:position played on team / speciality] ?parent_position .}
?child wdt:[property:instance of] wd:[entity:human] ;
wdt:[property:occupation] wd:[entity:ice hockey player]; # child's occupation = ice hockey player
wdt:[property:date of birth] ?child_born;
OPTIONAL {?child wdt:[property:sex or gender] ?child_gender.}
OPTIONAL {?child wdt:[property:position played on team / speciality] ?child_position.}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

