PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT (COUNT (DISTINCT ?spouse) AS ?count) WHERE {
?spouse wdt:[property:spouse] wd:[entity:Madonna] .
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en" .
}
}

query:
SELECT ?wikidata_item ?biosphere_reserve_name ?biosphereURL
WHERE {
?wikidata_item wdt:P2520 ?biosphereURL . # get a list of all biospheres
FILTER NOT EXISTS { ?wikidata_item wdt:P625 ?location.} # no location
?wikidata_item rdfs:label ?biosphere_reserve_name filter (lang(?biosphere_reserve_name) = "en").
}

SELECT ?stationLabel ?coord ?layer
WHERE {
?station wdt:P81/wdt:P361 wd:Q68646 .
?station wdt:P625 ?coord.
?station wdt:P81 ?line.
?line rdfs:label ?layer. filter(lang(?layer) = 'de')
SERVICE wikibase:label { bd:serviceParam wikibase:language "de" }
}

SELECT ?class ?classname ?property ?propertyname WHERE {
?tree0 (wdt:P279)* ?class .
BIND (wd:Q875538 AS ?tree0)
?class wdt:P1963 ?property .
SERVICE wikibase:label {
bd:serviceParam wikibase:language "en" .
?class rdfs:label ?classname .
?property rdfs:label ?propertyname .
}
}

SELECT ?item ?itemLabel ?nomLabel ?naissanceLabel ?coord ?debut ?fin ?matches WHERE {
?item wdt:P31 wd:Q5;
wdt:P106 wd:Q937857.
OPTIONAL { ?item wdt:P734 ?nom. }
?item wdt:P19 ?naissance.
?naissance wdt:P625 ?coord .
?item p:P54 ?om.
?om ps:P54 wd:Q132885.
OPTIONAL { ?om pq:P580 ?debut. }
OPTIONAL { ?om pq:P582 ?fin. }
OPTIONAL { ?om pq:P1350 ?matches. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],fr, en". }
}

annotated:
