PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?nomLabel ?naissanceLabel ?coord ?debut ?fin ?matches WHERE {
?item wdt:[property:instance of] wd:[entity:human];
wdt:[property:occupation] wd:[entity:association football player].
OPTIONAL { ?item wdt:[property:family name] ?nom. }
?item wdt:[property:place of birth] ?naissance.
?naissance wdt:[property:coordinate location] ?coord .
?item p:[property:member of sports team] ?om.
?om ps:[property:member of sports team] wd:[entity:Olympique de Marseille].
OPTIONAL { ?om pq:[property:start time] ?debut. }
OPTIONAL { ?om pq:[property:end time] ?fin. }
OPTIONAL { ?om pq:[property:number of matches played/races/starts] ?matches. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],fr, en". }
}

query:
