SELECT ?person ?personLabel ?ORCID ?award ?awardLabel ?ddate WHERE
{
?person wdt:[property:award received] ?award.
?person wdt:[property:instance of] wd:[entity:human].
?award wdt:[property:subclass of]* ?type.
?type wdt:[property:instance of] wd:[entity:Nobel Prize].
OPTIONAL { ?person wdt:[property:ORCID iD] ?ORCID. }
OPTIONAL { ?person wdt:[property:date of death] ?ddate.
FILTER(?ddate > "2012-01-01T00:00:00Z"^^xsd:dateTime) }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

query:
SELECT DISTINCT ?item ?ncbi_gene ?date_modified
WHERE
{
?item wdt:P351 ?ncbi_gene ;
wdt:P703 wd:Q15978631 ;
schema:dateModified ?date_modified .
BIND (now() - ?date_modified as ?date_range)
FILTER (?date_range < 8)
}

