PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?age ?birth_date WHERE {
?item wdt:[property:instance of] wd:[entity:human];
(p:[property:date of birth]/psv:[property:date of birth]) _:b8.
_:b8 wikibase:timeValue ?birth_date;
wikibase:timePrecision ?precision.
?item wdt:[property:occupation] wd:[entity:Australian rules football player];
wdt:[property:member of sports team] wd:[entity:Hawthorn Football Club].
FILTER(NOT EXISTS { ?item wdt:[property:date of death] ?dead. })
BIND(((YEAR(NOW())) - (YEAR(?birth_date))) - (IF(((MONTH(NOW())) < (MONTH(?birth_date))) || (((MONTH(NOW())) = (MONTH(?birth_date))) && ((DAY(NOW())) < (DAY(?birth_date)))), 1 , 0 )) AS ?age)
FILTER(?age >= 80 )
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC (?age)

query:
SELECT DISTINCT ?item ?scientific_name ?common_name ?length ?life_expectency ?height ?wing_span ?mass WHERE {
?item wdt:P225 ?scientific_name;
wdt:P1843 ?common_name.
OPTIONAL { ?item wdt:P2043 ?length. }
OPTIONAL { ?item wdt:P2250 ?life_expectency. }
OPTIONAL { ?item wdt:P2048 ?height. }
OPTIONAL { ?item wdt:P2050 ?wing_span. }
# Adult mass only. Excludes birth mass
OPTIONAL {
?item p:P2067 ?mass_statement_node.
?mass_statement_node pq:P642 wd:Q78101716;
ps:P2067 ?mass.
}
# Only return common names in English
FILTER(LANGMATCHES(LANG(?common_name), "en"))
# List of animals. All lowercase to avoid capitalisation issues
FILTER(lcase(str(?scientific_name)) IN (
"mustela erminea",
"aquila adalberti",
"vespula germanica",
"accipiter nisus",
"buteo buteo"
))
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

