query:
SELECT DISTINCT ?film ?filmLabel ?realLabel ?familleLabel ?duree (MIN(?date) as ?oldest_date) ?acces
WHERE
{
?film p:P3301 ?artfilm.
?artfilm ps:P3301 ?artfilmCH;
pq:P2699 ?URL.
FILTER STRSTARTS(STR(?URL), "https://www.artfilm.ch").
OPTIONAL {?film wdt:P2047 ?duree.}
OPTIONAL {?film wdt:P57 ?real.}
OPTIONAL {?film wdt:P577 ?date.}
OPTIONAL {?real wdt:P734 ?famille.}
?real wdt:P21 wd:Q6581072.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,de,it,es".
?real rdfs:label ?realLabel.
?film rdfs:label ?filmLabel.
?famille rdfs:label ?familleLabel.
}
}
GROUP BY ?film ?filmLabel ?realLabel ?familleLabel ?duree ?acces
ORDER BY STR(?familleLabel) ?realLabel ?oldest_date

SELECT ?country ?countryLabel (COUNT(DISTINCT ?item) AS ?count) WHERE {
?item wdt:P31/wdt:P279* wd:Q179700 ; wdt:P17 ?country ; wdt:P180 ?depicts .
?depicts wdt:P31 wd:Q5 ; wdt:P21 wd:Q6581072 .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?count)

SELECT ?qualifierpropertyLabel (COUNT(?creatorqualifier) AS ?count) WHERE {
?item wdt:P31 wd:Q3305213 .
?item wdt:P170 wd:Q4233718 .
OPTIONAL { ?item p:P170 ?creatorstatement .
?creatorstatement rdf:type wikibase:BestRank .
?creatorstatement ?qualifier ?creatorqualifier .
?qualifierproperty wikibase:qualifier ?qualifier }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} GROUP BY ?qualifierpropertyLabel
HAVING (?count > 2)
LIMIT 2000

SELECT ?print ?printLabel ?image ?pop ?popLabel ?popCoords ?subject ?subjectLabel ?subjectCoords ?line ?layer WHERE {
$print wdt:P361 wd:Q21542493 ;
wdt:P291 ?pop .
OPTIONAL { ?print wdt:P18 ?image .}
?pop wdt:P625 ?popCoords .
?pop p:P625 [ ps:P625 []; psv:P625 [ wikibase:geoLongitude ?poplon; wikibase:geoLatitude ?poplat; ] ].
$print p:P921 ?printstmt .
?printstmt ps:P921 ?subject .
?subject wdt:P625 ?subjectCoords .
?subject p:P625 [
ps:P625 [];
psv:P625 [
wikibase:geoLongitude ?subjectlon;
wikibase:geoLatitude ?subjectlat;
]
].
?pop rdfs:label ?layer .
FILTER (LANG(?layer) = "en")
BIND(CONCAT('LINESTRING (', STR(?poplon), ' ', STR(?poplat), ',', STR(?subjectlon), ' ', STR(?subjectlat), ')') AS ?str) .
BIND(STRDT(?str, geo:wktLiteral) AS ?line)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

