{
# query without labels
SELECT ?item (SAMPLE(?image) as ?image) (MIN(?whatever_date) as ?date)
WHERE
{
# item must be a videogame or any subclass of copyright license
wd:[entity:video game] ^wdt:[property:subclass of]*/^wdt:[property:instance of] ?item.
# item must has a license
?item wdt:[property:copyright license] ?license.
# the license must be a libre license
?libre_license ^wdt:[property:subclass of]*/^wdt:[property:instance of] ?license.
VALUES ?libre_license {
wd:[entity:open-source license] # open source
wd:[entity:free software license] # free software
wd:[entity:free license] # free license
wd:[entity:free license] # open license
}
OPTIONAL {
?item wdt:[property:image] ?image.
}
# item must have a date (whatever publication date or inception date is fine)
?item wdt:[property:publication date]|wdt:[property:inception] ?whatever_date.
}
GROUP BY ?item
}
# apply labels after the group by
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

query:
