SELECT ?count ?topic ?taxonname
WITH {
  SELECT (COUNT(?publication) AS ?count) ?topic WHERE {
    ?publication wdt:P921 ?topic .
    ?topic wdt:P105 wd:Q7432 .
  }
  GROUP BY ?topic
  ORDER BY DESC(?count)
  LIMIT 100
} AS %result
WHERE {
  INCLUDE %result
  ?topic wdt:P225 ?taxonname .
}
ORDER BY DESC(?count)

