PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?x ?xLabel ?loc ?layer ?img ?line ?birthplace ?birthplaceLabel ?teamLabel WITH {
SELECT ?team ?inception WHERE {
BIND ( wd:[entity:Arsenal F.C.] AS ?team )
?team wdt:[property:inception] ?inception .
}} AS %team
WITH { SELECT ?num ?start ?end ?gap WHERE {
INCLUDE %team
BIND (10 * FLOOR(YEAR(?inception) / 10) AS ?start)
BIND (10 AS ?gap )
BIND (10 * FLOOR(YEAR(NOW()) / 10) AS ?end )
BIND ( (?end - ?start ) / ?gap + 1 AS ?x )
[] p:[property:instance of] [
ps:[property:instance of] wd:[entity:natural number] ;
pq:[property:follows] ?prev].
?prev wdt:[property:numeric value] ?num .
FILTER (?num > 0 && ?num <= ?x )
} } AS %range
WITH { SELECT ?decade WHERE {
INCLUDE %range
BIND (?start + (?num - 1) * ?gap AS ?decade)
} ORDER BY ?decade }
AS %decades
WITH { SELECT ?x ?start_year ?end_year ?team WHERE {
INCLUDE %team
BIND ( NOW() AS ?today )
?x wdt:[property:instance of] wd:[entity:human].
?x p:[property:member of sports team] ?stmt.
?stmt ps:[property:member of sports team] ?team.
?stmt pq:[property:start time] ?start.
OPTIONAL { ?stmt pq:[property:end time] ?end }
BIND ( IF (wikibase:isSomeValue(?end), ?today, ?end ) AS ?new_end)
BIND(COALESCE(?new_end, ?today) as ?new_end)
BIND (YEAR(?start) AS ?start_year)
BIND (YEAR(?new_end) AS ?end_year)
} } AS %players
WHERE {
INCLUDE %players
INCLUDE %decades
?x wdt:[property:place of birth] ?birthplace.
?birthplace wdt:[property:coordinate location] ?loc.
OPTIONAL { ?x wdt:[property:image] ?img }
FILTER ( (?start_year >= ?decade && ?start_year < ?decade + 10) || (?end_year < ?decade + 10 && ?end_year >= ?decade ) || (?decade > ?start_year && ?decade < ?end_year ))
?birthplace p:[property:coordinate location] [
ps:[property:coordinate location] [];
psv:[property:coordinate location] [
wikibase:geoLongitude ?poblon;
wikibase:geoLatitude ?poblat;
]] .
?team wdt:[property:home venue] ?home .
?home p:[property:coordinate location] [
ps:[property:coordinate location] [];
psv:[property:coordinate location] [
wikibase:geoLongitude ?centrelon;
wikibase:geoLatitude ?centrelat]] .
BIND(CONCAT('LINESTRING (', STR(?poblon), ' ', STR(?poblat), ',', STR(?centrelon), ' ', STR(?centrelat), ')') AS ?str) .
BIND(STRDT(?str, geo:wktLiteral) AS ?line)
BIND(CONCAT(STR(?decade),"s") AS ?layer)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ASC(?layer)

