PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT
(?female_organizers / (?male_organizers + ?female_organizers) AS ?organizer_ratio)
?female_organizers ?male_organizers
(?female_authors / (?male_authors + ?female_authors) AS ?author_ratio)
?female_authors ?male_authors
?event ?eventLabel ?eventDescription
{
{
SELECT
?event
(COUNT(DISTINCT ?male_organizer) AS ?male_organizers)
(COUNT(DISTINCT ?female_organizer) AS ?female_organizers)
(COUNT(DISTINCT ?male_author) AS ?male_authors)
(COUNT(DISTINCT ?female_author) AS ?female_authors)
{
VALUES ?event_type { wd:[entity:academic conference] wd:[entity:academic workshop] }
?event wdt:[property:instance of] ?event_type .
?proceedings wdt:[property:is proceedings from] ?event .
{
?event wdt:[property:organizer] ?male_organizer .
?male_organizer wdt:[property:sex or gender] wd:[entity:male] .
}
UNION
{
?event wdt:[property:organizer] ?female_organizer .
?female_organizer wdt:[property:sex or gender] wd:[entity:female] .
}
{
?work wdt:[property:published in] ?proceedings ; wdt:[property:author] ?male_author .
?male_author wdt:[property:sex or gender] wd:[entity:male] .
}
UNION
{
?work wdt:[property:published in] ?proceedings ; wdt:[property:author] ?female_author .
?female_author wdt:[property:sex or gender] wd:[entity:female] .
}
}
GROUP BY ?event
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?male_organizers)

query:
SELECT DISTINCT ?name ?work_link ?work ?creatorLabel ?date
WITH {
SELECT ?creator WHERE {
VALUES ?citizenship {wd:Q145 wd:Q174193} . # UK, Britain & Ireland
?creator wdt:P6698 []; # Only get things with a Japan Search ID
wdt:P27 ?citizenship; wdt:P106 wd:Q1281618} # sculptors
} AS %creators
WHERE {
include %creators
SERVICE <https://jpsearch.go.jp/rdf/sparql/> {
?jps_creator owl:sameAs ?creator . # convert Wikidata ID to Japan Search ID
?work schema:creator ?jps_creator . # Works by this artist
OPTIONAL {?work schema:name ?name } # This will return separate names in English and Japanese names
OPTIONAL {?work schema:dateCreated ?date}
}
FILTER (lang(?name)="en") # Show only the English name
BIND(URI( REPLACE(STR(?work), "/data/", "/item/") ) AS ?work_link)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY ?date

