query:
SELECT ?river ?riverLabel (?lengthInM/1000 AS ?lengthInKm) ?mouthLabel WITH {
SELECT DISTINCT ?river ?lengthInM ?mouth WHERE {
?river wdt:P31/wdt:P279* wd:Q4022;
wdt:P403 ?mouth;
p:P2043 ?lengthStatement. ?lengthStatement a wikibase:BestRank; psn:P2043/wikibase:quantityAmount ?lengthInM. hint:Prior hint:rangeSafe true.
MINUS { ?mouth wdt:P31/wdt:P279* wd:Q165. }
MINUS { ?mouth wdt:P31/wdt:P279* wd:Q9430. }
FILTER(?lengthInM > 1000000)
}
ORDER BY DESC(?lengthInM)
LIMIT 10
} AS %results WHERE {
INCLUDE %results.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?lengthInM)

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psn: <http://www.wikidata.org/prop/statement/value-normalized/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?river ?riverLabel (?lengthInM/1000 AS ?lengthInKm) ?mouthLabel WITH {
SELECT DISTINCT ?river ?lengthInM ?mouth WHERE {
?river wdt:[property:instance of]/wdt:[property:subclass of]* wd:[entity:river];
wdt:[property:mouth of the watercourse] ?mouth;
p:[property:length] ?lengthStatement. ?lengthStatement a wikibase:BestRank; psn:[property:length]/wikibase:quantityAmount ?lengthInM. hint:Prior hint:rangeSafe true.
MINUS { ?mouth wdt:[property:instance of]/wdt:[property:subclass of]* wd:[entity:sea]. }
MINUS { ?mouth wdt:[property:instance of]/wdt:[property:subclass of]* wd:[entity:ocean]. }
FILTER(?lengthInM > 1000000)
}
ORDER BY DESC(?lengthInM)
LIMIT 10
} AS %results WHERE {
INCLUDE %results.
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?lengthInM)

query:
