query:
SELECT DISTINCT ?personLabel ?bookLabel ?page WHERE {
?book wdt:P50 ?person.
?person wdt:P19 ?place.
?place wdt:P131+ wd:Q12694.
?page schema:about ?book .
?page schema:isPartOf <https://fr.wikisource.org/> .
SERVICE wikibase:label { bd:serviceParam wikibase:language "fr". }
}
ORDER BY ?personLabel

SELECT DISTINCT ?item ?itemLabel ?countryLabel ?area ?population ?density ?coords
WHERE
{
?item p:P31 ?statement ;
wdt:P17 ?country ;
wdt:P625 ?coords .
?statement ps:P31/wdt:P279* wd:Q10864048 .
FILTER NOT EXISTS { ?statement pq:P582 ?x }
FILTER NOT EXISTS { ?country wdt:P31 wd:Q3024240 }
FILTER NOT EXISTS { ?item wdt:P576 ?x }
?item p:P2046 ?areaStatement .
{ FILTER NOT EXISTS { ?areaStatement pq:P518 ?x } } #UNION
#{ ?areaStatement pq:P518 wd:Q16868672 }
?areaStatement psv:P2046 [
wikibase:quantityAmount ?baseArea;
wikibase:quantityUnit [
p:P2370/psv:P2370 [
wikibase:quantityAmount ?unitArea;
wikibase:quantityUnit wd:Q25343
]
]
].
BIND(ROUND(?baseArea * ?unitArea / 1000000) AS ?area) .
FILTER (?area >= 100000)
?item wdt:P1082 ?population .
BIND(ROUND(100 * ?population / ?area) / 100 AS ?density)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?area)

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?item ?itemLabel ?countryLabel ?area ?population ?density ?coords
WHERE
{
?item p:[property:instance of] ?statement ;
wdt:[property:country] ?country ;
wdt:[property:coordinate location] ?coords .
?statement ps:[property:instance of]/wdt:[property:subclass of]* wd:[entity:first-level administrative division] .
FILTER NOT EXISTS { ?statement pq:[property:end time] ?x }
FILTER NOT EXISTS { ?country wdt:[property:instance of] wd:[entity:historical country] }
FILTER NOT EXISTS { ?item wdt:[property:dissolved, abolished or demolished date] ?x }
?item p:[property:area] ?areaStatement .
{ FILTER NOT EXISTS { ?areaStatement pq:[property:applies to part] ?x } } #UNION
#{ ?areaStatement pq:[property:applies to part] wd:[entity:whole] }
?areaStatement psv:[property:area] [
wikibase:quantityAmount ?baseArea;
wikibase:quantityUnit [
p:[property:conversion to SI unit]/psv:[property:conversion to SI unit] [
wikibase:quantityAmount ?unitArea;
wikibase:quantityUnit wd:[entity:square metre]
]
]
].
BIND(ROUND(?baseArea * ?unitArea / 1000000) AS ?area) .
FILTER (?area >= 100000)
?item wdt:[property:population] ?population .
BIND(ROUND(100 * ?population / ?area) / 100 AS ?density)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?area)

query:
