query:
SELECT ?p ?ct (COUNT(?i) as ?jumlah) WHERE {
OPTIONAL { SERVICE wikibase:label { bd:serviceParam wikibase:language "id".
?p rdfs:label ?namap.} }
?i wdt:P31 wd:Q5;
wdt:P570 ?dod.
FILTER(YEAR(?dod)>2018)
?i wdt:P509 ?p.
BIND(YEAR(?dod) as ?t)
BIND(CONCAT(?namap, " ", STR(?t)) as ?ct)
}
GROUP BY ?p ?ct
#defaultView:BubbleChart

