query:
SELECT ?prop ?item ?itemLabel ?inventory (GROUP_CONCAT(?typeLabel; separator=", ") AS ?types) ?from (YEAR(?latest) AS ?to) ?precision WHERE {
?item p:P195 [ps:P195 wd:Q636400; pq:P217 ?inventory].
?item ?prop wd:Q48129717; wdt:P31 ?type.
OPTIONAL {?item p:P571 [pq:P1319 ?earliest; pq:P1326 ?latest] }
OPTIONAL {?item p:P571/psv:P571 [ wikibase:timePrecision ?precision; wikibase:timeValue ?year ] }
BIND(IF (BOUND(?earliest), YEAR(?earliest), YEAR(?year)) AS ?from)
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
?item rdfs:label ?itemLabel. ?type rdfs:label ?typeLabel }
} GROUP BY ?prop ?item ?itemLabel ?inventory ?from ?latest ?precision
ORDER BY DESC(?prop) ?from ?to

SELECT ?coauthor_countryLabel (COUNT(?author1) AS ?numberOfCoAuthors)
WITH {
SELECT (COUNT(?work) AS ?count) ?author1 ?author2 WHERE {
# Find co-authors
?searched_author wdt:P496 "0000-0002-6778-0887".
?work wdt:P50 ?searched_author, ?author1, ?author2 .
}
GROUP BY ?author1 ?author2
ORDER BY DESC(?count)
# Limit the size of the graph, to avoid overburdening the browser
LIMIT 1000
} AS %authors
WITH {
SELECT ?author1 ?author2 ?coauthor_country WHERE {
INCLUDE %authors
# Exclude self-links
FILTER (?author1 != ?author2)
?author1 wdt:P27 ?coauthor_country.
}
} AS %result
WHERE {
INCLUDE %result
# Label the results
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,fr,de,ru,es,zh,jp". }
}GROUP BY ?coauthor_countryLabel
ORDER BY DESC(?numberOfCoAuthors)

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?coauthor_countryLabel (COUNT(?author1) AS ?numberOfCoAuthors)
WITH {
SELECT (COUNT(?work) AS ?count) ?author1 ?author2 WHERE {
# Find co-authors
?searched_author wdt:[property:ORCID iD] "0000-0002-6778-0887".
?work wdt:[property:author] ?searched_author, ?author1, ?author2 .
}
GROUP BY ?author1 ?author2
ORDER BY DESC(?count)
# Limit the size of the graph, to avoid overburdening the browser
LIMIT 1000
} AS %authors
WITH {
SELECT ?author1 ?author2 ?coauthor_country WHERE {
INCLUDE %authors
# Exclude self-links
FILTER (?author1 != ?author2)
?author1 wdt:[property:country of citizenship] ?coauthor_country.
}
} AS %result
WHERE {
INCLUDE %result
# Label the results
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,fr,de,ru,es,zh,jp". }
