SELECT ?author1 ?author1Label ?img ?rgb ?author2 ?author2Label
WITH {
SELECT (COUNT(?item) AS ?count) ?author1 ?author2 WHERE {
?item wdt:P8433 ?riks.
?item wdt:P50 ?author1,?author2.
?item wdt:P577 ?pubDate
FILTER ( Year(?pubDate) = 2018)
}
GROUP BY ?author1 ?author2
ORDER BY DESC(?count)
}
AS %authors
WITH {
SELECT ?author1 ?author2 ?img ?rgb WHERE {
INCLUDE %authors
# Exclude self-links
FILTER (?author1 != ?author2)
# Color according to party
OPTIONAL {
?author1 wdt:P102 ?party .
OPTIONAL {?party wdt:P154 ?img }
OPTIONAL {?party wdt:P465 ?rgb }
}
}
} AS %result
WHERE {
INCLUDE %result
# Label the results
SERVICE wikibase:label { bd:serviceParam wikibase:language "en,sv". }
}

