query:
SELECT distinct ?partyLabel ?seatLabel ?mpLabel ?image ?coords ?rgb (?partyLabel AS ?layer)
where {
?mp p:P39 ?currps . ?currps ps:P39 ?currterm . ?currterm wdt:P279 wd:Q16707842 .
filter not exists { ?currps pq:P582 ?currend } .
?currps pq:P768 ?seat . ?seat wdt:P625 ?coords . ?currps pq:P4100 ?party .
optional { ?mp wdt:P18 ?image }
?party wdt:P465 ?rgb .
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
#defaultView:Map{"hide":["?coords", "?layer", "?rgb"]}

SELECT ?ratio (COUNT(?item) AS ?count) WHERE {
?item wdt:P31/wdt:P279* wd:Q3305213 .
?item p:P2048/psv:P2048 [
wikibase:quantityAmount ?baseHeight;
wikibase:quantityUnit [
p:P2370/psv:P2370 [
wikibase:quantityAmount ?unitHeight;
wikibase:quantityUnit wd:Q11573
]
]
].
BIND(?baseHeight * ?unitHeight AS ?height).
?item p:P2049/psv:P2049 [
wikibase:quantityAmount ?baseWidth;
wikibase:quantityUnit [
p:P2370/psv:P2370 [
wikibase:quantityAmount ?unitWidth;
wikibase:quantityUnit wd:Q11573
]
]
].
BIND(?baseWidth * ?unitWidth AS ?width).
BIND(?height / ?width AS ?r) .
BIND(IF(?r<0.5,"< 0.5",
IF(?r<0.6,"0.5 - 0.6",
IF(?r<0.7,"0.6 - 0.7",
IF(?r<0.8,"0.7 - 0.8",
IF(?r<0.9,"0.8 - 0.9",
IF(?r<1.0,"0.9 - 1.0",
IF(?r<1.1,"1.0 - 1.1",
IF(?r<1.2,"1.1 - 1.2",
IF(?r<1.3,"1.2 - 1.3",
IF(?r<1.4,"1.3 - 1.4",
IF(?r<1.5,"1.4 - 1.5", "> 1.5"))))))))))) AS ?ratio) .
}
GROUP BY ?ratio
ORDER BY DESC(?count)

SELECT ?item1 ?image ?item1Label ?item2 ?image2 ?item2Label ?edgeLabel
WITH { SELECT ?item1 WHERE {
VALUES ?item1 {wd:Q8279 wd:Q43459 wd:Q82133 wd:Q8462 wd:Q53676578 wd:Q3147516 wd:Q553204 wd:Q20737645 wd:Q507564 wd:Q60809157 wd:Q1601879 wd:Q5943957 wd:Q1459037}
} } AS %item1
WITH {SELECT (?item1 AS ?item2) WHERE {INCLUDE %item1} } AS %item2
WHERE {
INCLUDE %item1.
INCLUDE %item2.
?item1 ?prop ?item2.
?edge ?dummy ?prop ; rdf:type wikibase:Property
OPTIONAL {?item1 wdt:P18 ?image}
OPTIONAL {?item2 wdt:P18 ?image2}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

