SELECT ?musee ?annee ?visiteurs ?museeLabel WHERE {
{
SELECT ?musee ?annee (AVG(?nb) AS ?visiteurs) WHERE {
{
SELECT ?musee (STR(YEAR(?date)) AS ?annee) ?nb WHERE {
VALUES ?musee { wd:[entity:Muséum Henri-Lecoq] wd:[entity:Musée d'Art Roger-Quilliot] wd:[entity:Musée Bargoin] }
?musee p:[property:visitors per year] ?node.
?node ps:[property:visitors per year] ?nb ; pq:[property:point in time] ?date.
}
}
}
GROUP BY ?musee ?annee
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

query:
