?work wdt:[property:author] ?author .
OPTIONAL { ?citing_work wdt:[property:cites work] ?work . }
OPTIONAL {
?author wdt:[property:affiliation] | wdt:[property:employer] ?organization_ .
?organization_ wdt:[property:country] wd:[entity:Turkey]
}
}
GROUP BY ?author
} AS %results
WHERE {
INCLUDE %results
service wikibase:label { bd:serviceParam wikibase:language "en" . }
}
ORDER BY DESC(?number_of_citing_works)

