BIND (ROUND(?l) AS ?length)
FILTER( ?length >= 50 )
VALUES ?type { wd:Q573344 wd:Q355304 wd:Q4022 wd:Q3073652 }
?river wdt:P31 ?type .
?river wdt:P4614+ ?basin .
?basin wdt:P138 ?basinName .
FILTER NOT EXISTS { ?basinName wdt:P403/wdt:P31 wd:Q573344 }
FILTER NOT EXISTS { ?basinName wdt:P403/wdt:P31 wd:Q4022 }
FILTER NOT EXISTS { ?basinName wdt:P31 wd:Q165 }
FILTER NOT EXISTS { ?basinName wdt:P31 wd:Q9430 }
FILTER NOT EXISTS { ?basinName wdt:P31 wd:Q39594 }
FILTER NOT EXISTS { ?basinName wdt:P31 wd:Q1973404 }
FILTER NOT EXISTS { ?basin wdt:P31 wd:Q82794 }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
}
OPTIONAL { ?river wdt:P3896 ?shape }
BIND(?basinNameLabel AS ?layer)
}
