PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>

SELECT DISTINCT ?wditem ?wditemLabel ?date ?image ?work ?workLabel WHERE {
SERVICE <http://dbpedia.org/sparql> {
?item dct:subject|dct:subject/skos:broader dbc:History_of_telecommunications ;
owl:sameAs ?wditem FILTER regex (?wditem, "wikidata.org") .
}
SERVICE <https://query.wikidata.org/sparql> {
{?wditem wdt:[property:date of birth] ?date FILTER (YEAR(?date)>1700).}
UNION
{?wditem wdt:[property:inception]|wdt:[property:publication date]|wdt:[property:start time] ?date .}
OPTIONAL {?wditem wdt:[property:notable work] ?work. ?work rdfs:label ?workLabel FILTER (LANG(?workLabel)="en") .}
OPTIONAL {?wditem wdt:[property:image] ?image } .
?wditem rdfs:label ?wditemLabel FILTER (LANG(?wditemLabel)="en") .
}
}

query:
SELECT DISTINCT ?item ?itemLabel ?born ?father ?fatherLabel ?fatherdied ?days_posthumous WHERE {
?item p:P39 ?statement. ?statement ps:P39 ?position . ?position wdt:P279* wd:Q16707842 .
?item wdt:P569 ?born .
?item wdt:P22 ?father . ?father wdt:P570 ?fatherdied . filter(?fatherdied < ?born) .
bind(round((?born-?fatherdied)) as ?days_posthumous) .
filter(?days_posthumous < 1000) # omit one massively wrong
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} order by ?born

SELECT DISTINCT ?t ?rrLabel ?valueLabel ?image
WHERE
{
{wd:Q57191 ?prop ?t FILTER (datatype(?t)=xsd:dateTime) .
?value wikibase:directClaim ?prop. }
UNION
{
wd:Q57191 ?q ?statement FILTER regex (STR(?q),"prop/P") .
?statement ?p ?t FILTER regex (STR(?p), "prop/qualifier/P") FILTER (datatype(?t)=xsd:dateTime) .
?statement ?r ?value FILTER regex (STR(?r),"prop/statement/") .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?r),1,29),"direct/"),SUBSTR(STR(?r),40))) as ?rprop)
?rr wikibase:directClaim ?rprop .
OPTIONAL {?value wdt:P18 ?image}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

