?item (wdt:[property:instance of]/(wdt:[property:subclass of]*)) wd:[entity:GLAM];
(p:[property:coordinate location]/psv:[property:coordinate location]) _:b12.
_:b12 wikibase:geoLatitude ?northernmostLat.
