?p wdt:[property:occupation] wd:[entity:philosopher]; wdt:[property:date of birth] ?dob.
FILTER ((YEAR(?dob) > 100) && (YEAR(?dob) < 500)).
BIND (xsd:integer(FLOOR(YEAR(?dob) / 100) * 100) AS ?ic_cent).
BIND (xsd:integer(FLOOR(YEAR(?dob) / 1000) * 1000) AS ?ic_milyear).
}}UNION{
SELECT ?i_p ?iu_p ?ii_p ?ic_dec ?rn_t_dob ?ic_dob ?rn_t_dod ?ic_dod ?rn_country ?i_country WHERE{
?i_p wdt:[property:occupation] wd:[entity:philosopher]; wdt:[property:date of birth] ?ic_dob.
FILTER ((YEAR(?ic_dob) > 100) && (YEAR(?ic_dob) < 500)).
BIND (xsd:integer(FLOOR(YEAR(?ic_dob) / 10) * 10) AS ?ic_dec).
?rn_t_dob wikibase:directClaim wdt:[property:date of birth].
OPTIONAL { ?i_p wdt:[property:date of death] ?ic_dod. ?rn_t_dod wikibase:directClaim wdt:[property:date of death]. }
BIND (CONCAT (STR (?i_p), "SSif") AS ?iu_p).
OPTIONAL { ?i_p wdt:[property:image] ?ii_p. }
BIND ("country" AS ?rn_country).
OPTIONAL { ?i_p wdt:[property:country of citizenship] ?i_country. }
}}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

